import { test } from "node:test";
import assert from "node:assert/strict";

import { AztecEncoder } from "../src/encode/matrix/aztec-encoder.ts";
import { readMatrixFixture } from "./matrix-fixtures.ts";

/**
 * Conformance test: the Node port must reproduce, module-for-module, the Aztec symbol matrix of the
 * Java implementation (the shared goldens under {@code src/test/resources/golden/matrix}).
 */
const INPUTS: string[] = [
  "https://github.com/ronison/bars4j",
  "Bars4J",
  "1234567890",
  "AZTEC".repeat(8),
  "ISO/IEC 24778 Aztec barcode generated by Bars4J. ".repeat(25),
];

for (let i = 0; i < INPUTS.length; i++) {
  test(`AZTEC-${i} module matrix matches golden`, () => {
    const symbol = new AztecEncoder().encode(INPUTS[i]);
    const fixture = readMatrixFixture("AZTEC", i);

    assert.equal(symbol.widthInModules(), fixture.width, "width");
    assert.equal(symbol.heightInModules(), fixture.height, "height");
    assert.equal(symbol.quietZone(), fixture.quietZone, "quiet zone");
    assert.deepEqual(symbol.modules(), fixture.rows, `matrix mismatch for AZTEC-${i}`);
  });
}
